package com.vms.vendorcontractmanagement.entity; import jakarta.persistence.*; import lombok.*; import java.time.*; import java.util.*;
@Entity @Table(name="vendors") @Getter @Setter @NoArgsConstructor public class Vendor { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="vendor_id") Long id; @Column(unique=true) String vendorCode; String vendorName,category,contactEmail,phone,country,status="ACTIVE"; @ManyToOne @JoinColumn(name="owner_user_id") User owner; LocalDateTime createdAt; @ManyToMany @JoinTable(name="vendor_departments",joinColumns=@JoinColumn(name="vendor_id"),inverseJoinColumns=@JoinColumn(name="department_id")) Set<Department> departments=new HashSet<>(); @PrePersist void created(){createdAt=LocalDateTime.now();} }
